{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "At the start of stage 1, how many tools do you already have in working (available) condition?",
    "How many are already in repair (and if so, when each becomes available)?"
  ],
  "rationale": "The response asks for the count of tools in working condition and separately for the count of tools in repair along with their availability times. These are distinct data points that can be answered independently."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a tool is sent for slow repair at the end of stage j, is it unavailable for the entire duration of stages j+1 through j+p-1 and back in working condition at the start of stage j+p, or does it instead return at the end of stage j+p (i.e., first usable in stage j+p+1)?"
  ],
  "rationale": "The response asks for a single policy choice regarding the exact timing of tool availability after repair, presenting two mutually exclusive options for one underlying question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For fast repair, is the timing the same pattern — a tool sent for fast repair at the end of stage j is unavailable only during stage j+1 and back in working condition at the start of stage j+q (so with q=1 it is available again at the start of the very next stage)?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of a specific timing pattern for fast repair."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "At the end of each stage, can a tool be sent for repair only if it is actually broken/needed to be repaired, or can you choose to send any working tool for repair (slow or fast) as a strategic choice, regardless of whether it is broken?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding repair eligibility (mandatory vs. optional/strategic)."
}

